-- Query 1: Movies vs TV ShowsSELECT type,COUNT(*) AS total_titlesFROM netflixGROUP BY type;-- Query 2: Top 10 CountriesSELECT country,COUNT(*) AS total_titlesFROM netflixGROUP BY countryORDER BY total_titles DESCLIMIT 10;-- Query 3: Rating DistributionSELECT rating,COUNT(*) AS total_titlesFROM netflixGROUP BY ratingORDER BY total_titles DESC;-- Query 4: Content Released Each YearSELECT release_year,COUNT(*) AS total_titlesFROM netflixGROUP BY release_yearORDER BY release_year;-- Query 5: Recent ContentSELECT title,release_yearFROM netflixWHERE release_year >= 2020;